insert into public.learning_questions (id, stage_id, display_order, prompt, explanation)
values
  ('f2bdebaa-d6b9-4842-99ae-f7be36fc65ce', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 1, '23+14의 값은?', '일의 자리 3+4=7, 십의 자리 2+1=3이므로 23+14=37입니다.'),
  ('7e25f698-6a28-4c6f-9e6e-11f0aad911eb', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 2, '42+35의 값은?', '일의 자리 2+5=7, 십의 자리 4+3=7이므로 42+35=77입니다.'),
  ('8911ee70-d4e8-41bd-ac73-fa73a7a9df83', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 3, '68-25의 값은?', '일의 자리 8-5=3, 십의 자리 6-2=4이므로 68-25=43입니다.'),
  ('e828c3e3-7033-40d6-b4a1-bfbead5c7746', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 4, '94-32의 값은?', '일의 자리 4-2=2, 십의 자리 9-3=6이므로 94-32=62입니다.'),
  ('ddbf1059-a184-49b4-8e39-33ad6f17283e', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 5, '빨간 색종이가 21장이고 파란 색종이가 16장입니다. 모두 몇 장인가요?', '21장과 16장을 모으면 21+16=37이므로 모두 37장입니다.'),
  ('b3ef9b19-5f36-46d6-a4a2-df1ddafd228f', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 6, '연필 58자루 중 24자루를 쓰면 몇 자루가 남나요?', '58자루에서 24자루를 빼면 58-24=34이므로 34자루가 남습니다.'),
  ('6010da6e-98e2-4456-a421-bf9fedbf6b3b', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 7, '32명과 15명을 합한 수를 구하는 식은?', '''합한 수''는 덧셈으로 구하므로 32+15=47입니다.'),
  ('9a51b222-5275-4b45-accb-03306711e4a8', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 8, '76개 중 22개를 주고 남은 수를 구하는 식은?', '''남은 수''는 전체에서 준 수를 빼어 76-22=54로 구합니다.'),
  ('8bccea31-7d34-4a0d-afa2-a3f1e783d33b', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 9, '34+25와 72-14를 비교한 것은?', '34+25=59이고 72-14=58이므로 34+25가 1만큼 더 큽니다.'),
  ('77113c21-f902-4cae-8314-dfab963886c8', 'da1b89e9-6091-4f25-8e76-9e205c6a72a0', 10, '41+□=68일 때 □에 들어갈 수는?', '68-41=27이므로 41+27=68입니다.'),
  ('10b46024-d55e-4cec-bccc-eaa9c6d7c5cd', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 1, '27+38의 값은?', '7+8=15에서 5를 쓰고 1을 받아올리면 2+3+1=6이므로 65입니다.'),
  ('e2ea6ae8-1dbd-4dfe-b9f3-da790b7cb01b', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 2, '46+29의 값은?', '6+9=15에서 5를 쓰고 1을 받아올리면 4+2+1=7이므로 75입니다.'),
  ('6427e95f-7440-43e8-9ec6-88f20cefc80f', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 3, '52-28의 값은?', '2에서 8을 빼기 어려워 1십을 받아 12-8=4, 4-2=2이므로 24입니다.'),
  ('9e6623dc-0214-4a00-83b0-f2df830d0187', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 4, '71-46의 값은?', '1에서 6을 빼기 어려워 1십을 받아 11-6=5, 6-4=2이므로 25입니다.'),
  ('e18aa374-17aa-43b1-a9b4-917fb017f020', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 5, '도서관에 동화책 38권과 과학책 27권이 있습니다. 두 종류의 책은 모두 몇 권인가요?', '38+27=65이므로 두 종류의 책은 모두 65권입니다.'),
  ('6453343a-af00-4e7c-a6a4-cd81352a9766', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 6, '공 83개 중 47개를 사용했습니다. 남은 공은 몇 개인가요?', '83-47=36이므로 남은 공은 36개입니다.'),
  ('e6855eb1-ec59-4c3d-ab3f-99196a2eb82c', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 7, '파란 구슬 26개와 노란 구슬 18개를 모았습니다. 알맞은 식은?', '두 묶음을 모았으므로 26+18=44입니다.'),
  ('088aab4c-8832-4017-8f95-81d59b37a668', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 8, '64장의 색종이 중 29장을 사용했습니다. 알맞은 식은?', '전체 64장에서 사용한 29장을 빼면 64-29=35입니다.'),
  ('47fb7468-014a-43b0-8713-6be1e69c1c6f', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 9, '47+26과 90-18을 비교한 것은?', '47+26=73이고 90-18=72이므로 47+26이 1만큼 더 큽니다.'),
  ('b7761c69-14b4-42b3-b9dc-9c1ffcbef992', '75bd76ea-b5e4-4b89-ac30-e7be1eaba1d5', 10, '36+□=82일 때 □에 들어갈 수는?', '82-36=46이므로 36+46=82입니다.'),
  ('de2bc462-9d6a-4783-b9f2-5b027374c1d3', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 1, '48+27과 39+35의 결과를 비교한 것은?', '48+27=75, 39+35=74이므로 48+27이 1만큼 더 큽니다.'),
  ('4a1f1041-92b1-4b69-8fd3-428c4d0cf6ca', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 2, '84-39와 72-28의 결과를 비교한 것은?', '84-39=45, 72-28=44이므로 84-39가 1만큼 더 큽니다.'),
  ('86dfd93c-721c-4d4f-b3a5-0d03613f60bf', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 3, '□+28=73일 때 □에 들어갈 수는?', '73-28=45이므로 45+28=73입니다.'),
  ('5f96017d-fb5d-4f38-9d56-cd71d2e7d225', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 4, '91-□=46일 때 □에 들어갈 수는?', '91-46=45이므로 91-45=46입니다.'),
  ('a5ce51f3-81ea-4f55-aefd-defd5d2961cf', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 5, '책 36권에 28권을 더 가져온 뒤 17권을 빌려주었습니다. 남은 책은 몇 권인가요?', '36+28=64이고 64-17=47이므로 47권이 남습니다.'),
  ('f4e78b1f-7e1b-4645-8a16-95765cc99ad4', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 6, '구슬 74개 중 26개를 주고 15개를 더 받았습니다. 지금 구슬은 몇 개인가요?', '74-26=48이고 48+15=63이므로 지금 구슬은 63개입니다.'),
  ('5c012423-db06-4977-be4b-83860d0eb1f8', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 7, '연필 45자루 중 18자루를 주고 12자루를 더 받았습니다. 알맞은 식과 답은?', '먼저 준 18을 빼고 받은 12를 더하면 45-18+12=39입니다.'),
  ('95472b55-daa9-44f7-b84e-d7087b41eaea', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 8, '56+18과 93-17의 결과를 비교한 것은?', '56+18=74, 93-17=76이므로 93-17이 2만큼 더 큽니다.'),
  ('85f87c04-593d-4d07-a20e-4c9d7078ae80', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 9, '3□+27=65일 때 □에 들어갈 숫자는?', '65-27=38이므로 3□는 38이고 □에 들어갈 숫자는 8입니다.'),
  ('ccf47455-a946-4a99-84b2-5cab58b3840f', '2fb7c1d4-c5b0-4b4c-a276-0ff09ae45331', 10, '82-□=47일 때 □에 들어갈 수는?', '82-47=35이므로 82-35=47입니다.'),
  ('2a6282ff-83fe-4086-b312-cc89240d0dd3', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 1, '민수는 38+27을 55라고 계산했습니다. 틀린 이유는?', '7+8=15의 받아올림 1을 십의 자리에 더해야 하므로 올바른 답은 65입니다.'),
  ('d4de18fb-eea5-401f-be99-374a6cbbd536', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 2, '지우는 72-38을 46이라고 계산했습니다. 바른 설명은?', '72-38은 1십을 받아내림하여 12-8=4, 6-3=3으로 계산하므로 34입니다.'),
  ('e0e10c90-c21b-44ee-8d14-dbffd1b947c3', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 3, '계산이 잘못된 것은?', '46+28은 6+8=14에서 1을 받아올리면 74입니다. 64라는 계산은 잘못되었습니다.'),
  ('e3e8e8d8-9987-4d52-b098-88e4feb730b1', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 4, '81-46을 계산하는 방법으로 올바른 것은?', '81-46은 1십을 받아 11-6=5, 7-4=3으로 계산하여 35입니다.'),
  ('32f3e6e8-efe1-48d9-af39-88ab086d2f97', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 5, '두 수의 합은 83이고 한 수는 47입니다. 다른 한 수는?', '83-47=36이므로 다른 한 수는 36입니다.'),
  ('b84e6faa-8527-418e-b55a-45da84c69f52', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 6, '두 수의 차이는 28이고 작은 수는 39입니다. 큰 수는?', '큰 수는 작은 수에 차이를 더해 39+28=67입니다.'),
  ('52146340-686a-4f04-a33f-6f102967d9a2', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 7, '□+38=72입니다. □에 들어갈 수는?', '72-38=34이므로 34+38=72입니다.'),
  ('9aed200e-49ff-406e-85c0-fcc05f38a643', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 8, '사과가 65개 있는데 27개를 먹었습니다. 수호는 65+27로 계산했습니다. 바른 설명은?', '먹은 사과는 전체에서 없어지므로 65-27=38입니다.'),
  ('82b5875a-97dc-42fb-9e51-a4a807ffe95c', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 9, '민호는 57+28=75, 지수는 92-18=74라고 했습니다. 바르게 비교한 것은?', '57+28은 받아올림하여 85이고 92-18=74이므로 민호의 올바른 결과가 더 큽니다.'),
  ('e040742f-f7eb-4e67-a95b-05a9ddb0078d', '8ba52eca-c986-4897-bdd8-9a7da4e6f271', 10, '어떤 수에 26을 더했더니 71이 되었습니다. 그 수에서 18을 빼면?', '먼저 71-26=45로 어떤 수를 찾고 45-18=27을 구합니다.');

